class Solution {
public:
    int countBattleships(vector<vector<char>>& board) {
        int ships = 0;
        for (int r = 0; r < (int)board.size(); r++) {
            for (int c = 0; c < (int)board[0].size(); c++) {
                if (board[r][c] != 'X') continue;
                if (r > 0 && board[r - 1][c] == 'X') continue;
                if (c > 0 && board[r][c - 1] == 'X') continue;
                ships++;
            }
        }
        return ships;
    }
};
